/* ---------- intrusion alert email ----------
   Preferred: RESEND_API_KEY secret (resend.com, free) -> ALERT_EMAIL (no default — set ALERT_EMAIL).
   Fallback:  WEB3FORMS_KEY (optional; emails the inbox registered to that key).
   Anti-flood: alerts fire on attempt 1, 3, 5 and 8 (lockout) per IP per 15-minute window. */
async function sendAlert(env, ev, attempts) {
  const to = env.ALERT_EMAIL; if (!to) return;   /* set ALERT_EMAIL (+ RESEND_API_KEY) to enable email alerts */
  const when = new Date(ev.t).toLocaleString('en-CA', { timeZone: 'America/Toronto' });
  const where = [ev.city, ev.country].filter(Boolean).join(', ') || 'unknown';
  const status = attempts >= 8 ? 'LOCKED OUT (15 min)' : `${8 - attempts} attempts remaining before lockout`;
  const subject = `HQ — intrusion attempt #${attempts} from ${ev.ip}`;
  const text = `HQ door alert\n\nWrong passphrase at the gate.\n\nWhen:     ${when}\nIP:       ${ev.ip}\nLocation: ${where}\nDevice:   ${ev.ua}\nStatus:   ${status}\n\nOpen the app -> Settings -> Security -> Door log for the full history.\nIf this was you, ignore. If not, consider changing the passphrase (Worker -> Settings -> Variables -> PASSPHRASE).`;
  const html = `<div style="font-family:ui-monospace,Menlo,monospace;background:#120303;color:#FFE9E7;padding:28px;border-radius:14px;max-width:560px">
    <div style="font-size:11px;letter-spacing:.3em;color:#FF7A72">HQ · DOOR ALERT</div>
    <h2 style="margin:10px 0 18px;font-size:22px;color:#FF5A52">Intrusion attempt #${attempts}</h2>
    <table style="font-size:13px;line-height:1.9;color:#FFD9D6;border-collapse:collapse">
      <tr><td style="color:#FF9A94;padding-right:16px">When</td><td>${when}</td></tr>
      <tr><td style="color:#FF9A94;padding-right:16px">IP</td><td><b>${ev.ip}</b></td></tr>
      <tr><td style="color:#FF9A94;padding-right:16px">Location</td><td>${where}</td></tr>
      <tr><td style="color:#FF9A94;padding-right:16px">Device</td><td>${ev.ua}</td></tr>
      <tr><td style="color:#FF9A94;padding-right:16px">Status</td><td><b>${status}</b></td></tr>
    </table>
    <p style="font-size:12px;color:#C9A3A0;margin-top:18px">Full history: app → Settings → Security → Door log.<br>Not you? Rotate the passphrase in the Worker's Variables.</p></div>`;
  try {
    if (env.RESEND_API_KEY) {
      await fetch('https://api.resend.com/emails', {
        method: 'POST',
        headers: { 'Authorization': 'Bearer ' + env.RESEND_API_KEY, 'Content-Type': 'application/json' },
        body: JSON.stringify({ from: env.ALERT_FROM || 'HQ <onboarding@resend.dev>', to: [to], subject, text, html })
      });
      return;
    }
    const w3 = env.WEB3FORMS_KEY; if (!w3) return;
    await fetch('https://api.web3forms.com/submit', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
      body: JSON.stringify({ access_key: w3, subject, from_name: 'HQ Security', replyto: to, message: text })
    });
  } catch (e) { /* alerts never block auth */ }
}

const SETUP_PAGE = LOCK_PAGE
  .replace('<h1>HQ · OPERATOR ACCESS</h1>', '<h1>HQ · FIRST RUN</h1><p style="font-size:12px;color:#83907F;max-width:300px;margin:-14px auto 20px;line-height:1.6">Set the passphrase that guards this HQ. Minimum 8 characters. You can rotate it later from the Worker\'s Variables.</p>')
  .replace('placeholder="passphrase" autocomplete="current-password"', 'placeholder="create passphrase" autocomplete="new-password"')
  .replace('<button type="submit">UNLOCK</button>', '<input id="p2" type="password" placeholder="confirm" autocomplete="new-password" style="margin-top:8px"><button type="submit">CREATE &amp; ENTER</button>')
  .replace("const r=await fetch('/api/auth'", "if($('#p').value!==$('#p2').value){$('#err').textContent='PASSPHRASES DO NOT MATCH';return;}const r=await fetch('/api/setup'")
  .replace("breach(info);", "$('#err').textContent=(info&&info.err?info.err.toUpperCase():'COULD NOT SET UP');");

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    // Passphrase source: env.PASSPHRASE (if you set one) or a KV-stored salted hash created on first run.
    let cfg = null; try { cfg = JSON.parse((await env.HQ_KV.get('auth')) || 'null'); } catch (e) {}
    const NEEDS_SETUP = !env.PASSPHRASE && !cfg;
    const secretSeed = env.PASSPHRASE || (cfg && cfg.hash) || 'unset';
    const expected = await hmac(secretSeed, 'hq-session-v1');
    const authed = !NEEDS_SETUP && safeEq(getCookie(request, COOKIE) || '', expected);
    const checkPass = async (p) => {
      if (env.PASSPHRASE) return safeEq(p, env.PASSPHRASE);
      if (!cfg) return false;
      return safeEq(await hmac(cfg.salt, p), cfg.hash);
    };

    // ---- first-run setup: create the door passphrase (only possible while none exists) ----
    if (url.pathname === '/api/setup' && request.method === 'POST') {
      if (!NEEDS_SETUP) return new Response(JSON.stringify({ ok: false, err: 'already set up' }), { status: 409, headers: { 'Content-Type': 'application/json' } });
      let body = {}; try { body = await request.json(); } catch (e) {}
      const p = String(body.pass || '');
      if (p.length < 8) return new Response(JSON.stringify({ ok: false, err: 'min 8 characters' }), { status: 400, headers: { 'Content-Type': 'application/json' } });
      const salt = [...crypto.getRandomValues(new Uint8Array(16))].map(b => b.toString(16).padStart(2, '0')).join('');
      const hash = await hmac(salt, p);
      await env.HQ_KV.put('auth', JSON.stringify({ salt, hash, t: Date.now() }));
      const exp2 = await hmac(hash, 'hq-session-v1');
      return new Response(JSON.stringify({ ok: true }), { headers: { 'Content-Type': 'application/json',
        'Set-Cookie': `${COOKIE}=${exp2}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=31536000` } });
    }

    if (url.pathname === '/api/auth' && request.method === 'POST') {
      // throttle: 8 failures per IP per 15 minutes -> 429
      const ip = request.headers.get('CF-Connecting-IP') || 'x';
      const rlKey = 'auth:fail:' + ip;
      const fails = parseInt((await env.HQ_KV.get(rlKey)) || '0', 10);
      if (fails >= 8) return new Response(JSON.stringify({ ok: false, throttled: true, ip, attempts: fails }), { status: 429, headers: { 'Content-Type': 'application/json', 'Retry-After': '900' } });
      let body = {};
      try { body = await request.json(); } catch (e) {}
      if (!(typeof body.pass === 'string' && await checkPass(body.pass))) {
        await env.HQ_KV.put(rlKey, String(fails + 1), { expirationTtl: 900 });
        // door log: last 25 failed attempts, visible inside the app (Settings -> Security)
        let log = []; try { log = JSON.parse((await env.HQ_KV.get('doorlog')) || '[]'); } catch (e) {}
        log.unshift({ t: Date.now(), ip, ua: (request.headers.get('User-Agent') || '').slice(0, 120), country: request.headers.get('CF-IPCountry') || '', city: (request.cf && request.cf.city) || '' });
        await env.HQ_KV.put('doorlog', JSON.stringify(log.slice(0, 25)));
        const n = fails + 1;
        if ([1, 3, 5, 8].includes(n)) { const p = sendAlert(env, log[0], n); if (ctx && ctx.waitUntil) ctx.waitUntil(p); else await p; }
        return new Response(JSON.stringify({ ok: false, attempts: n, ip }), { status: 401, headers: { 'Content-Type': 'application/json' } });
      }
      await env.HQ_KV.delete(rlKey);
      return new Response(JSON.stringify({ ok: true }), { headers: {
        'Content-Type': 'application/json',
        'Set-Cookie': `${COOKIE}=${expected}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=31536000`
      }});
    }
    if (url.pathname === '/api/logout') {
      return new Response('bye', { headers: { 'Set-Cookie': `${COOKIE}=; Path=/; Max-Age=0` } });
    }

    // POST /api/coach {prompt, context} -> Claude via server-side key (optional)
    if (url.pathname === '/api/coach' && request.method === 'POST') {
      if (!authed) return new Response('unauthorized', { status: 401 });
      if (!env.ANTHROPIC_API_KEY) return new Response(JSON.stringify({ err: 'no key' }), { status: 501, headers: { 'Content-Type': 'application/json' } });
      let b = {}; try { b = await request.json(); } catch (e) {}
      const prompt = String(b.prompt || '').slice(0, 2000);
      const context = String(b.context || '').slice(0, 4000);
      const r = await fetch('https://api.anthropic.com/v1/messages', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'x-api-key': env.ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01' },
        body: JSON.stringify({ model: 'claude-sonnet-4-6', max_tokens: 1000, messages: [{ role: 'user', content:
          "You are the user's personal strength coach inside their dashboard. Terse, sharp, honest — a corner-man, not a cheerleader. No emoji, no markdown headers, short lines. Context: " + context + "\n\nThey say: " + prompt }] })
      });
      if (!r.ok) return new Response(JSON.stringify({ err: 'upstream' }), { status: 502, headers: { 'Content-Type': 'application/json' } });
      const data = await r.json();
      const text = (data.content || []).filter(x => x.type === 'text').map(x => x.text).join('\n').trim();
      return new Response(JSON.stringify({ text }), { headers: { 'Content-Type': 'application/json' } });
    }

    // media (avatar/banner) lives in its own key so state pushes stay lean
    if (url.pathname === '/api/media') {
      if (!authed) return new Response('unauthorized', { status: 401 });
      if (request.method === 'GET') {
        const v = await env.HQ_KV.get('media');
        return new Response(v || 'null', { headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' } });
      }
      if (request.method === 'PUT' || request.method === 'POST') {
        const body = await request.text();
        if (body.length > 6 * 1024 * 1024) return new Response('too large', { status: 413 });
        try { JSON.parse(body); } catch (e) { return new Response('bad json', { status: 400 }); }
        await env.HQ_KV.put('media', body);
        return new Response(JSON.stringify({ ok: true }), { headers: { 'Content-Type': 'application/json' } });
      }
      return new Response('method', { status: 405 });
    }
    if (url.pathname === '/api/doorlog') {
      if (!authed) return new Response('unauthorized', { status: 401 });
      if (request.method === 'DELETE') { await env.HQ_KV.put('doorlog', '[]'); return new Response('{"ok":true}', { headers: { 'Content-Type': 'application/json' } }); }
      const v = await env.HQ_KV.get('doorlog');
      return new Response(v || '[]', { headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' } });
    }
    if (url.pathname === '/api/state') {
      if (!authed) return new Response('unauthorized', { status: 401 });
      if (request.method === 'GET') {
        const v = await env.HQ_KV.get('state');
        return new Response(v || 'null', { headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' } });
      }
      if (request.method === 'PUT' || request.method === 'POST') {
        const body = await request.text();
        if (body.length > 20 * 1024 * 1024) return new Response('too large', { status: 413 });
        let incoming; try { incoming = JSON.parse(body); } catch (e) { return new Response('bad json', { status: 400 }); }
        const curRaw = await env.HQ_KV.get('state');
        // guard: never let an older snapshot overwrite a newer one (stale tab / slow device clock)
        if (curRaw) {
          try {
            const cur = JSON.parse(curRaw);
            if ((incoming.t || 0) < (cur.t || 0)) {
              return new Response(JSON.stringify({ ok: false, stale: true, t: cur.t }), { status: 409, headers: { 'Content-Type': 'application/json' } });
            }
          } catch (e) {}
        }
        // rolling backups: before the first write of each day, snapshot current state
        const today = new Date().toISOString().slice(0, 10);
        const last = await env.HQ_KV.get('lastBackupDay');
        if (last !== today && curRaw) {
          await env.HQ_KV.put('backup:' + new Date().getDay(), curRaw);
          await env.HQ_KV.put('lastBackupDay', today);
        }
        await env.HQ_KV.put('state', body);
        return new Response(JSON.stringify({ ok: true }), { headers: { 'Content-Type': 'application/json' } });
      }
      return new Response('method', { status: 405 });
    }

    // GET /api/backup?day=0..6 -> view a snapshot | POST /api/restore {day} -> roll back to it
    if (url.pathname === '/api/backup') {
      if (!authed) return new Response('unauthorized', { status: 401 });
      const v = await env.HQ_KV.get('backup:' + (url.searchParams.get('day') || '0'));
      return new Response(v || 'null', { headers: { 'Content-Type': 'application/json' } });
    }
    if (url.pathname === '/api/restore' && request.method === 'POST') {
      if (!authed) return new Response('unauthorized', { status: 401 });
      let b = {}; try { b = await request.json(); } catch (e) {}
      const v = await env.HQ_KV.get('backup:' + (b.day ?? 0));
      if (!v) return new Response(JSON.stringify({ ok: false, err: 'no backup in that slot' }), { status: 404, headers: { 'Content-Type': 'application/json' } });
      await env.HQ_KV.put('state', v);
      return new Response(JSON.stringify({ ok: true }), { headers: { 'Content-Type': 'application/json' } });
    }

    if (url.pathname.startsWith('/icon-') || url.pathname.startsWith('/apple-touch-icon')) {
      if (url.pathname.startsWith('/icon-192')) return png(ICON_192);
      if (url.pathname.startsWith('/icon-512')) return png(ICON_512);
      return png(ICON_APPLE);
    }
    if (!authed) return new Response(NEEDS_SETUP ? SETUP_PAGE : LOCK_PAGE, { headers: { 'Content-Type': 'text/html;charset=UTF-8', 'Cache-Control': 'no-store' } });

    if (url.pathname === '/sw.js') return new Response(SW_JS, { headers: { 'Content-Type': 'application/javascript', 'Cache-Control': 'no-store' } });
    if (url.pathname === '/manifest.webmanifest') return new Response(MANIFEST, { headers: { 'Content-Type': 'application/manifest+json' } });
    if (url.pathname === '/icon-192.png') return png(ICON_192);
    if (url.pathname === '/icon-512.png') return png(ICON_512);
    if (url.pathname === '/apple-touch-icon.png' || url.pathname === '/apple-touch-icon-precomposed.png' || url.pathname.startsWith('/apple-touch-icon')) return png(ICON_APPLE);
    return new Response(APP_HTML, { headers: { 'Content-Type': 'text/html;charset=UTF-8', 'Cache-Control': 'no-store' } });
  }
};
